    else if (!(Option(e.tenantId).isDefined)) Some(iMadzError("EVENT_BAD_ID", "WorkgroupNameUpdated.tenantId 必须存在"))
    // @knowledge ed634767-d073-4616-a8bd-be1ec8fdd18a@25068721404ffd58
    // ir_evt_WorkgroupNameUpdated_timestamp
    else if (!(Option(e.timestamp).isDefined)) Some(iMadzError("EVENT_NO_TIMESTAMP", "WorkgroupNameUpdated.timestamp 不能为空"))
    // @knowledge ed634767-d073-4616-a8bd-be1ec8fdd18a@25068721404ffd58
    // ir_evt_WorkgroupNameUpdated_workgroupId_not_null
    else if (!(Option(e.workgroupId).isDefined)) Some(iMadzError("EVENT_BAD_ID", "WorkgroupNameUpdated.workgroupId 必须存在"))
    else None

}
